var src = msg.payload || {};
var obj = src.object;
var di = src.deviceInfo || {};
if (!obj || typeof obj !== 'object') return null;

var deviceName = di.deviceName || '';
var profileName = di.deviceProfileName || '';
var devEui = (di.devEui || '').toLowerCase();

var measurement = 'lorawan_misc';
if (/^dl[_-]?iam/i.test(deviceName) || /dl[_-]?iam/i.test(profileName)) {
    var d = deviceName.match(/dl[_-]?iam[_-]?(\d+)/i);
    measurement = d ? ('dl_iam_' + d[1]) : 'dl_iam_unknown';
} else {
    var m = deviceName.match(/lora[_-]?radio[_-]?(\d+)/i);
    if (m && m[1]) {
        measurement = 'zigbee_network_' + m[1];
    } else if (/lora[_-]?radio/i.test(deviceName) || /lora[_-]?radio/i.test(profileName)) {
        measurement = 'zigbee_network_edge';
    }
}

var round2 = function(v) {
    return (typeof v === 'number' && v % 1 !== 0) ? Math.round(v * 100) / 100 : v;
};

var baseTime = src.time ? new Date(src.time) : new Date();
if (isNaN(baseTime.getTime())) baseTime = new Date();
var shifted = new Date(baseTime.getTime() + (2 * 60 * 60 * 1000));
var timeGmt2 = shifted.toISOString().replace(/\.\d{3}Z$/, 'Z');

function isExcludedField(k) {
    return k === 'entry_id' || k === 'entryId' || k === 'entry-id' || k === 'protocol_version' || k === 'device_id';
}

function normalizeValue(v) {
    if (v === null || v === undefined) return undefined;
    if (typeof v === 'number') return round2(v);
    if (typeof v === 'boolean') return v ? 1 : 0;
    if (typeof v === 'string') return v;
    return JSON.stringify(v);
}

function applyAlarmIndicators(out, sensorObj) {
    var list = Array.isArray(sensorObj.alarm_fields) ? sensorObj.alarm_fields : [];
    var active = {};
    for (var i = 0; i < list.length; i++) {
        if (typeof list[i] === 'string' && list[i]) active[list[i]] = true;
    }
    out.alarm = list.length > 0 ? 1 : 0;
    out.alarm_count = list.length;
    out.alarm_fields = list.filter(function(v) { return typeof v === 'string' && v; }).join(',');
    var skipAlarmScalar = { entry_id: true, entryId: true, 'entry-id': true, sensor_type: true, alarm_fields: true, protocol_version: true, device_id: true };
    for (var ak in sensorObj) {
        if (!Object.prototype.hasOwnProperty.call(sensorObj, ak)) continue;
        if (skipAlarmScalar[ak] || isExcludedField(ak)) continue;
        var av = sensorObj[ak];
        if (av === null || av === undefined) continue;
        if (typeof av === 'object') continue;
        var safeKey = String(ak).replace(/[^a-zA-Z0-9_]/g, '_');
        if (!safeKey) continue;
        out['alarm_' + safeKey] = active[ak] ? 1 : 0;
    }
}

function buildPoint(sensorName, sensorObj) {
    if (!sensorObj || typeof sensorObj !== 'object' || Array.isArray(sensorObj)) return null;

    var out = {
        dev_eui: devEui,
        device_name: deviceName || devEui,
        sensor_name: deviceName || devEui,
        measurement: measurement,
        time_gmt2: timeGmt2
    };

    for (var k in sensorObj) {
        if (!Object.prototype.hasOwnProperty.call(sensorObj, k)) continue;
        if (isExcludedField(k)) continue;
        var val = normalizeValue(sensorObj[k]);
        if (val !== undefined) out[k] = val;
    }

    applyAlarmIndicators(out, sensorObj);

    return {
        topic: 'nodered/lorawan/' + measurement,
        payload: out
    };
}

var messages = [];
var keys = Object.keys(obj);
var hasNestedSensors = keys.some(function(k) {
    return obj[k] && typeof obj[k] === 'object' && !Array.isArray(obj[k]);
});

if (hasNestedSensors) {
    keys.forEach(function(sensorKey) {
        var point = buildPoint(sensorKey, obj[sensorKey]);
        if (point) messages.push(point);
    });
} else {
    var single = buildPoint('uplink_object', obj);
    if (single) messages.push(single);
}

if (messages.length === 0) return null;
var edgeDupes = [];
for (var mi = 0; mi < messages.length; mi++) {
    var p = messages[mi].payload;
    var mst = p.measurement;
    if (typeof mst === 'string' && mst.indexOf('zigbee_network_') === 0) {
        var ep = {};
        for (var ek in p) {
            if (Object.prototype.hasOwnProperty.call(p, ek)) ep[ek] = p[ek];
        }
        ep.measurement = 'lora_rpi_edge';
        ep.original_measurement = mst;
        edgeDupes.push({ topic: 'nodered/lorawan_edge', payload: ep });
    }
}
node.send([messages.concat(edgeDupes)]);
return null;
